302:   /**
303:    * Specifies the action to take if the an error occurs trying to produce the promised value, that the given predicate applies to.
304:    * <p>
305:    * If the given action throws an exception, the original exception will be rethrown with the exception thrown
306:    * by the action added to the suppressed exceptions list.
307:    *
308:    * @param predicate the predicate to test against the error
309:    * @param errorHandler the action to take if an error occurs
310:    * @return A promise for the successful result
311:    * @since 1.1
312:    */
313:   default Promise<T> onError(Predicate<? super Throwable> predicate, Action<? super Throwable> errorHandler) {
314:     return transform(up -> down ->
315:       up.connect(down.onError(throwable -> {
316:         if (predicate.apply(throwable)) {
317:           try {
318:             errorHandler.execute(throwable);
319:           } catch (Throwable e) {
320:             if (e != throwable) {
321:               e.addSuppressed(throwable);
322:             }
323:             down.error(e);
324:             return;
325:           }
326:           down.complete();
327:         } else {
328:           down.error(throwable);
329:         }
330:       }))
331:     );
332:   }
