34: /**
35:  * A promise for a single value.
36:  * <p>
37:  * A promise is a representation of a value which will become available later.
38:  * Methods such as {@link #map(Function)}, {@link #flatMap(Function)}, {@link #cache()} etc.) allow a pipeline of “operations” to be specified,
39:  * that the value will travel through as it becomes available.
40:  * Such operations are implemented via the {@link #transform(Function)} method.
41:  * Each operation returns a new promise object, not the original promise object.
42:  * <p>
43:  * To create a promise, use the {@link Promise#async(Upstream)} method (or one of the variants such as {@link Promise#sync(Factory)}.
44:  * To test code that uses promises, use the {@link ratpack.test.exec.ExecHarness}.
45:  * <p>
46:  * The promise is not “activated” until the {@link #then(Action)} method is called.
47:  * This method terminates the pipeline, and receives the final value.
48:  * <p>
49:  * Promise objects are multi use.
50:  * Every promise pipeline has a value producing function at its start.
51:  * Activating a promise (i.e. calling {@link #then(Action)}) invokes the function.
52:  * The {@link #cache()} operation can be used to change this behaviour.
53:  *
54:  * @param <T> the type of promised value
55:  */
56: @SuppressWarnings("JavadocReference")
57: public interface Promise<T> {
58: 
59:   /**
60:    * Creates a promise for value that will be produced asynchronously.
61:    * <p>
62:    * The {@link Upstream#connect(Downstream)} method of the given upstream will be invoked every time the value is requested.
63:    * This method should propagate the value (or error) to the given downstream object when it is available.
64:    *
65:    * <pre class="java">{@code
66:    * import ratpack.exec.Promise;
67:    * import ratpack.test.exec.ExecHarness;
68:    *
69:    * import static org.junit.Assert.assertEquals;
70:    *
71:    * public class Example {
72:    *   public static void main(String[] args) throws Exception {
73:    *     String value = ExecHarness.yieldSingle(e ->
74:    *       Promise.<String>async(down ->
75:    *         new Thread(() -> {
76:    *           down.success("foo");
77:    *         }).start()
78:    *       )
79:    *     ).getValueOrThrow();
80:    *
81:    *     assertEquals(value, "foo");
82:    *   }
83:    * }
84:    * }</pre>
85:    *
86:    * @param upstream the producer of the value
87:    * @param <T> the type of promised value
88:    * @return a promise for the asynchronously created value
89:    * @see Upstream
90:    * @see #sync(Factory)
91:    * @see #value(Object)
92:    * @see #error(Throwable)
93:    * @since 1.3
94:    */
95:   static <T> Promise<T> async(Upstream<T> upstream) {
96:     return new DefaultPromise<>(DefaultExecution.upstream(upstream));
97:   }
98: 
99:   /**
100:    * Creates a promise for value, synchronously, produced by the given factory.
101:    * <p>
102:    * The given factory will be invoked every time that the value is requested.
103:    * If the factory throws an exception, the promise will convey that exception.
104:    *
105:    * <pre class="java">{@code
106:    * import ratpack.exec.Promise;
107:    * import ratpack.test.exec.ExecHarness;
108:    *
109:    * import static org.junit.Assert.assertEquals;
110:    *
111:    * public class Example {
112:    *   public static void main(String[] args) throws Exception {
113:    *     String value = ExecHarness.yieldSingle(e ->
114:    *       Promise.sync(() -> "foo")
115:    *     ).getValueOrThrow();
116:    *
117:    *     assertEquals(value, "foo");
118:    *   }
119:    * }
120:    * }</pre>
121:    *
122:    * <p>
123:    * This method is often used to when a method needs to return a promise, but can produce its value synchronously.
124:    *
125:    * @param factory the producer of the value
126:    * @param <T> the type of promised value
127:    * @return a promise for the result of the factory
128:    * @see #async(Upstream)
129:    * @see #value(Object)
130:    * @see #error(Throwable)
131:    * @since 1.3
132:    */
133:   static <T> Promise<T> sync(Factory<T> factory) {
134:     return async(down -> {
135:       T t;
136:       try {
137:         t = factory.create();
138:       } catch (Exception e) {
139:         down.error(e);
140:         return;
141:       }
142:       down.success(t);
143:     });
144:   }
145: 
146:   /**
147:    * Creates a promise for the given item.
148:    * <p>
149:    * The given item will be used every time that the value is requested.
150:    *
151:    * <pre class="java">{@code
152:    * import ratpack.exec.Promise;
153:    * import ratpack.test.exec.ExecHarness;
154:    *
155:    * import static org.junit.Assert.assertEquals;
156:    *
157:    * public class Example {
158:    *   public static void main(String[] args) throws Exception {
159:    *     String value = ExecHarness.yieldSingle(e ->
160:    *       Promise.value("foo")
161:    *     ).getValueOrThrow();
162:    *
163:    *     assertEquals(value, "foo");
164:    *   }
165:    * }
166:    * }</pre>
167:    *
168:    * @param t the promised value
169:    * @param <T> the type of promised value
170:    * @return a promise for the given item
171:    * @see #async(Upstream)
172:    * @see #sync(Factory)
173:    * @see #error(Throwable)
174:    */
175:   static <T> Promise<T> value(T t) {
176:     return async(down -> down.success(t));
177:   }
178: 
179:   /**
180:    * Creates a failed promise with the given error.
181:    * <p>
182:    * The given error will be used every time that the value is requested.
183:    *
184:    * <pre class="java">{@code
185:    * import ratpack.exec.Promise;
186:    * import ratpack.test.exec.ExecHarness;
187:    *
188:    * import static org.junit.Assert.assertSame;
189:    *
190:    * public class Example {
191:    *   public static void main(String[] args) throws Exception {
192:    *     Exception exception = new Exception();
193:    *     Throwable error = ExecHarness.yieldSingle(e ->
194:    *       Promise.error(exception)
195:    *     ).getThrowable();
196:    *
197:    *     assertSame(exception, error);
198:    *   }
199:    * }
200:    * }</pre>
201:    *
202:    * @param t the error
203:    * @param <T> the type of promised value
204:    * @return a failed promise
205:    * @see #async(Upstream)
206:    * @see #sync(Factory)
207:    * @see #value(Object)
208:    */
209:   static <T> Promise<T> error(Throwable t) {
210:     return async(down -> down.error(t));
211:   }
212: 
213:   /**
214:    * Deprecated.
215:    *
216:    * @param upstream the producer of the value
217:    * @param <T> the type of promised value
218:    * @return a promise for the asynchronously created value
219:    * @deprecated replaced by {@link #async(Upstream)}
220:    */
221:   @Deprecated
222:   static <T> Promise<T> of(Upstream<T> upstream) {
223:     return async(upstream);
224:   }
225: 
226:   /**
227:    * Deprecated.
228:    *
229:    * @param factory the producer of the value
230:    * @param <T> the type of promised value
231:    * @return a promise for the result of the factory
232:    * @deprecated replaced by {@link #sync(Factory)}}
233:    */
234:   @Deprecated
235:   static <T> Promise<T> ofLazy(Factory<T> factory) {
236:     return sync(factory);
237:   }
