457:     return transform(up -> down -> up.connect(
458:       down.<T>onSuccess(value -> {
459:         try {
460:           O apply = transformer.apply(value);
461:           down.success(apply);
462:         } catch (Throwable e) {
463:           down.error(e);
464:         }
465:       })
466:       )
467:     );
468:   }
