600:    * <pre class="java">{@code
601:    * import ratpack.test.exec.ExecHarness;
602:    * import ratpack.exec.ExecResult;
603:    * import ratpack.exec.Promise;
604:    * import ratpack.exec.Operation;
605:    *
606:    * import com.google.common.collect.Lists;
607:    *
608:    * import java.util.concurrent.TimeUnit;
609:    * import java.util.Arrays;
610:    * import java.util.List;
611:    *
612:    * import static org.junit.Assert.assertEquals;
613:    *
614:    * public class Example {
615:    *
616:    *   public static class CaseService {
617:    *     public Operation toUpper(String value, List<String> values) {
618:    *       return Operation.of(() -> values.add(value.toUpperCase()));
619:    *     }
620:    *   }
621:    *
622:    *   public static void main(String... args) throws Exception {
623:    *     CaseService service = new CaseService();
624:    *     List<String> events = Lists.newLinkedList();
625:    *
626:    *     ExecHarness.runSingle(c ->
627:    *       Promise.value("foo")
628:    *        .nextOp(v -> service.toUpper(v, events))
629:    *        .then(events::add)
630:    *     );
