642:   default Promise<T> nextOp(Function<? super T, ? extends Operation> function) {
643:     return transform(up -> down -> up.connect(
644:       down.<T>onSuccess(value ->
645:         function.apply(value)
646:           .onError(down::error)
647:           .then(() ->
648:             down.success(value)
649:           )
650:       )
651:       )
652:     );
