1496:     return transform(up -> down ->
1497:       Promise.async(innerDown ->
1498:         releaser.execute((Runnable) () -> innerDown.success(true))
1499:       ).then(v ->
1500:         up.connect(down)
1501:       )
1502:     );
1503:   }
